<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, jsonRequest } from '../../shared/api/client'
import { account } from '../accounts/auth'
import { request, failure, openShare } from './social'
const props = defineProps<{ ruleId?: string }>()
const rules = ref<any[]>([]), scenes = ref<string[]>([]), selected = ref<any>(null), version = ref<any>(null)
const mine = ref(false), editor = ref(false), title = ref(''), summary = ref(''), tags = ref(''), error = ref(''), notice = ref(''), busy = ref(false)
const scene = ref('放松'), languages = ref(''), excluded = ref(''), maxArtist = ref(2), energyMax = ref<number | undefined>(), bpmMin = ref<number | undefined>(), bpmMax = ref<number | undefined>()
const excludedArtists = ref(''), excludedTracks = ref(''), vocals = ref('allowed'), energyMin = ref<number | undefined>(), variationMax = ref<number | undefined>(), rhythmMin = ref<number | undefined>(), reduceDuplicates = ref(true)
const unknown = ref('exclude'), source = ref('personal_first'), count = ref(20), goal = ref('count'), minutes = ref(45)
const weights = ref({ scene: 70, artist: 15, personal: 15 }), trial = ref<any>(null), editingId = ref(''), origin = ref<string | undefined>()
function optionalNumber(value: unknown) { return value === '' || value == null ? null : Number(value) }
function config() { return { scene: scene.value, filters: { languages: languages.value.split(/[,，]/).map(x => x.trim()).filter(Boolean), excluded_themes: excluded.value.split(/[,，]/).map(x => x.trim()).filter(Boolean), excluded_artists: excludedArtists.value.split(/[,，]/).map(x => x.trim()).filter(Boolean), excluded_tracks: excludedTracks.value.split(/[,，]/).map(x => x.trim()).filter(Boolean), vocals: vocals.value, energy_min: optionalNumber(energyMin.value), variation_max: optionalNumber(variationMax.value), rhythm_stability_min: optionalNumber(rhythmMin.value), energy_max: optionalNumber(energyMax.value), bpm_min: optionalNumber(bpmMin.value), bpm_max: optionalNumber(bpmMax.value), unknown_feature: unknown.value }, ranking: weights.value, diversity: { max_per_artist: maxArtist.value, reduce_duplicates: reduceDuplicates.value }, source_mode: source.value, output: { goal: goal.value, target_count: count.value, target_duration_minutes: minutes.value } } }
async function refresh() { const data = await request(`/rules?mine=${mine.value}`); rules.value = data.items; scenes.value = data.scenes }
async function open(id: string) { try { selected.value = await request(`/rules/${id}`); version.value = selected.value.versions.find((x: any) => x.id === selected.value.published_version_id) || selected.value.versions[0]; editor.value = false } catch (e) { error.value = failure(e) } }
function edit(fork = false) {
  const data = version.value?.config
  editingId.value = fork ? '' : selected.value?.id || ''; origin.value = fork ? version.value.id : undefined
  title.value = fork ? `${selected.value.title} · 改编` : selected.value?.title || ''; summary.value = selected.value?.summary || ''; tags.value = selected.value?.tags.join('，') || ''
  scene.value = data?.scene || '放松'; languages.value = data?.filters.languages.join('，') || ''; excluded.value = data?.filters.excluded_themes.join('，') || ''
  energyMax.value = data?.filters.energy_max ?? undefined; bpmMin.value = data?.filters.bpm_min ?? undefined; bpmMax.value = data?.filters.bpm_max ?? undefined
  weights.value = { ...(data?.ranking || { scene: 70, artist: 15, personal: 15 }) }; maxArtist.value = data?.diversity.max_per_artist || 2
  unknown.value = data?.filters.unknown_feature || 'exclude'; source.value = data?.source_mode || 'personal_first'; goal.value = data?.output.goal || 'count'; count.value = data?.output.target_count || 20; minutes.value = data?.output.target_duration_minutes || 45
  excludedArtists.value = data?.filters.excluded_artists?.join('，') || ''; excludedTracks.value = data?.filters.excluded_tracks?.join('，') || ''; vocals.value = data?.filters.vocals || 'allowed'; energyMin.value = data?.filters.energy_min ?? undefined; variationMax.value = data?.filters.variation_max ?? undefined; rhythmMin.value = data?.filters.rhythm_stability_min ?? undefined; reduceDuplicates.value = data?.diversity.reduce_duplicates ?? true
  editor.value = true; trial.value = null
}
async function save() { busy.value = true; error.value = ''; try { selected.value = await request(editingId.value ? `/rules/${editingId.value}/versions` : '/rules', 'POST', { title: title.value, summary: summary.value, tags: tags.value.split(/[,，]/).map(x => x.trim()).filter(Boolean), config: config(), origin_version_id: origin.value }); version.value = selected.value.versions[0]; editor.value = false; notice.value = '已保存新版本；发布后其他人才能复用。'; await refresh() } catch (e) { error.value = failure(e) } finally { busy.value = false } }
async function runTrial() { busy.value = true; error.value = ''; try { trial.value = await request('/rules/trial', 'POST', config()) } catch (e) { error.value = failure(e) } finally { busy.value = false } }
async function action(action: string) { try { await request(`/rules/${selected.value.id}/actions`, 'POST', { action, version_id: version.value.id }); notice.value = '操作已保存。'; await open(selected.value.id); await refresh() } catch (e) { error.value = failure(e) } }
async function reuse() {
  busy.value = true; error.value = ''
  try {
    const result = await api('/api/music/recommendations', { ...jsonRequest('POST', { need: `使用规则“${selected.value.title}”生成歌单`, rule_version_id: version.value.id, preferences: {} }), headers: { 'Content-Type': 'application/json', 'Idempotency-Key': crypto.randomUUID() } })
    notice.value = `已创建场景歌单任务。可在“场景歌单”的历史任务中查看，任务状态：${result.status}。`
  } catch (e) { error.value = failure(e) } finally { busy.value = false }
}
onMounted(async () => { try { await refresh(); if (props.ruleId) await open(props.ruleId) } catch (e) { error.value = failure(e) } })
</script>
<template>
  <section class="social-stack"><header class="social-section-heading"><div><span class="social-eyebrow">分享你的选歌方法</span><h2>规则广场</h2></div><div class="social-actions"><button @click="mine = !mine; refresh()">{{ mine ? '浏览广场' : '我的规则' }}</button><button class="primary" @click="selected = null; version = null; edit()">创建规则</button></div></header><p v-if="error" class="social-error" role="alert">{{ error }}</p><p v-if="notice" class="social-notice" role="status">{{ notice }}</p>
    <form v-if="editor" class="social-card social-rule-editor" @submit.prevent="save"><h3>{{ editingId ? '保存新的规则版本' : '创建规则草稿' }}</h3><div class="social-form-grid"><label>规则名称<input v-model="title" required maxlength="80" /></label><label>场景<select v-model="scene"><option v-for="item in scenes" :key="item">{{ item }}</option></select></label><label>语言（逗号分隔）<input v-model="languages" placeholder="中文，日文" /></label><label>排除主题<input v-model="excluded" placeholder="失恋" /></label><label>BPM 下限<input v-model.number="bpmMin" type="number" min="0" max="300" /></label><label>BPM 上限<input v-model.number="bpmMax" type="number" min="0" max="300" /></label><label>能量上限<input v-model.number="energyMax" type="number" min="0" max="1" step=".05" /></label><label>每位歌手最多<input v-model.number="maxArtist" type="number" min="1" max="20" /></label><label v-for="key in (['scene', 'artist', 'personal'] as const)" :key="key">{{ { scene: '场景权重', artist: '歌手权重', personal: '个人收藏权重' }[key] }}<input v-model.number="weights[key]" type="number" min="0" max="100" /></label><label>未知特征<select v-model="unknown"><option value="exclude">排除</option><option value="allow_unscored">允许，但不加分</option></select></label><label>来源<select v-model="source"><option value="personal_first">个人库优先</option><option value="personal_only">仅个人库</option><option value="discover">在线发现</option></select></label><label>输出目标<select v-model="goal"><option value="count">歌曲数量</option><option value="duration">总时长</option></select></label><label v-if="goal === 'count'">歌曲数<input v-model.number="count" type="number" min="1" max="50" /></label><label v-else>分钟数<input v-model.number="minutes" type="number" min="1" max="300" /></label></div><details><summary>更多筛选</summary><div class="social-form-grid"><label>排除歌手<input v-model="excludedArtists" placeholder="逗号分隔" /></label><label>排除歌曲标题<input v-model="excludedTracks" placeholder="逗号分隔" /></label><label>人声<select v-model="vocals"><option value="allowed">不限</option><option value="instrumental">仅纯音乐</option></select></label><label>能量下限<input v-model.number="energyMin" type="number" min="0" max="1" step=".05" /></label><label>变化程度上限<input v-model.number="variationMax" type="number" min="0" max="1" step=".05" /></label><label>节奏稳定性下限<input v-model.number="rhythmMin" type="number" min="0" max="1" step=".05" /></label><label class="social-check"><input v-model="reduceDuplicates" type="checkbox" />减少重复歌曲</label></div></details><label>说明<textarea v-model="summary" maxlength="500" /></label><label>标签<input v-model="tags" placeholder="逗号分隔" /></label><div class="social-actions"><button type="button" :disabled="busy" @click="runTrial">用我的音乐库试跑</button><button class="primary" :disabled="busy">保存草稿版本</button><button type="button" @click="editor = false">取消</button></div><p class="social-muted">试跑不调用模型；正式复用遵循场景歌单现有用量限制。</p><section v-if="trial"><h4>试跑入选 {{ trial.selected.length }} 首</h4><p v-for="item in trial.selected" :key="item.id">{{ item.title }} · {{ item.rule_reasons.join('；') }}</p><details><summary>查看淘汰原因（{{ trial.rejected.length }}）</summary><p v-for="(item, index) in trial.rejected" :key="index">{{ item.title }}：{{ item.reasons.join('；') }}</p></details></section></form>
    <article v-else-if="selected" class="social-card"><div class="social-section-heading"><h3>{{ selected.title }}</h3><button @click="selected = null">返回广场</button></div><p>{{ selected.summary }}</p><label>固定版本<select v-model="version"><option v-for="item in selected.versions" :key="item.id" :value="item">v{{ item.version }} · {{ new Date(item.created_at * 1000).toLocaleDateString() }}</option></select></label><p>{{ version.config.scene }} · {{ version.config.output.goal === 'count' ? `${version.config.output.target_count} 首` : `${version.config.output.target_duration_minutes} 分钟` }} · 每位歌手最多 {{ version.config.diversity.max_per_artist }} 首</p><details><summary>查看完整规则配置</summary><pre class="social-json">{{ JSON.stringify(version.config, null, 2) }}</pre></details><div class="social-actions"><button class="primary" :disabled="busy" @click="reuse">使用这个版本生成</button><button @click="action('save')">收藏版本</button><button @click="action('follow')">订阅更新</button><button @click="edit(true)">基于此规则改编</button><button v-if="selected.status === 'published' && version.id === selected.published_version_id" @click="openShare('rule', version.id, selected.title)">分享规则</button><template v-if="selected.author_id === account?.id"><button @click="edit(false)">创建新版本</button><button @click="action('publish')">发布所选版本</button><button @click="action('withdraw')">下架</button></template></div></article>
    <div v-else class="social-grid"><button v-for="item in rules" :key="item.id" class="social-card social-rule-card" @click="open(item.id)"><span class="social-eyebrow">{{ item.scene }} · {{ item.status === 'published' ? '已发布' : '草稿 / 已下架' }}</span><h3>{{ item.title }}</h3><p>{{ item.summary || '一种值得分享的选歌方法' }}</p><small>{{ item.author_name || '已注销用户' }} <span v-if="item.saved">· 已收藏</span></small><div class="social-tags"><span v-for="tag in item.tags" :key="tag">{{ tag }}</span></div></button></div><p v-if="!rules.length && !editor && !selected" class="social-empty">把适合自己的选歌方法，分享给朋友。</p>
  </section>
</template>
